[Form]
public class NVHcmWorkerSalaryDropDialog extends FormRun
{
    HcmWorkerRecId                workerRecId;
    boolean                       basicSalaryFound;
    NVHcmCompensationLevelPayroll gradePayroll;
}

public void init()
{
    super();

    workerRecId = this.resolveWorkerRecId();

    if (!workerRecId)
    {
        throw error("A worker record must be selected.");
    }

    this.defaultPosition();
    this.calculateSalary();
}

private HcmWorkerRecId resolveWorkerRecId()
{
    Common          callerRecord = element.args().record();
    FieldId         workerFieldId;
    HcmWorkerRecId  resolvedWorkerRecId;

    if (callerRecord)
    {
        if (callerRecord.TableId == tableNum(HcmWorker))
        {
            return callerRecord.RecId;
        }

        workerFieldId = fieldName2Id(callerRecord.TableId, identifierStr(Worker));

        if (workerFieldId)
        {
            resolvedWorkerRecId = callerRecord.(workerFieldId);
        }
    }

    if (!resolvedWorkerRecId && element.args().parm())
    {
        resolvedWorkerRecId = str2Int64(element.args().parm());
    }

    return resolvedWorkerRecId;
}

private void defaultPosition()
{
    TransDateTime               currentDateTime = DateTimeUtil::getSystemDateTime();
    HcmWorker                   worker          = HcmWorker::find(workerRecId);
    HcmPosition                 position;
    HcmPosition                 primaryPosition = HcmPosition::findByPosition(worker.primaryPositionId());
    HcmPositionWorkerAssignment workerPosition;
    Set                         assignedPositions = new Set(Types::Int64);
    HcmPositionId               onlyPositionId;
    HcmPositionId               primaryPositionId;

    while select workerPosition
        where workerPosition.Worker    == workerRecId
           && workerPosition.ValidFrom <= currentDateTime
           && workerPosition.ValidTo   >= currentDateTime
    {
        if (!assignedPositions.in(workerPosition.Position))
        {
            assignedPositions.add(workerPosition.Position);
            position       = HcmPosition::find(workerPosition.Position);
            onlyPositionId = position.PositionId;

            if (primaryPosition && workerPosition.Position == primaryPosition.RecId)
            {
                primaryPositionId = position.PositionId;
            }
        }
    }

    if (primaryPositionId)
    {
        PositionId.text(primaryPositionId);
    }
    else if (assignedPositions.elements() == 1)
    {
        PositionId.text(onlyPositionId);
    }
}

private void lookupPosition(FormStringControl _control)
{
    TransDateTime         currentDateTime = DateTimeUtil::getSystemDateTime();
    SysTableLookup        sysTableLookup  = SysTableLookup::newParameters(tableNum(HcmPosition), _control);
    Query                 query           = new Query();
    QueryBuildDataSource  positionQbds;
    QueryBuildDataSource  assignmentQbds;

    positionQbds   = query.addDataSource(tableNum(HcmPosition));
    assignmentQbds = positionQbds.addDataSource(tableNum(HcmPositionWorkerAssignment));

    assignmentQbds.relations(false);
    assignmentQbds.joinMode(JoinMode::ExistsJoin);
    assignmentQbds.addLink(fieldNum(HcmPosition, RecId), fieldNum(HcmPositionWorkerAssignment, Position));
    assignmentQbds.addRange(fieldNum(HcmPositionWorkerAssignment, Worker)).value(queryValue(workerRecId));
    assignmentQbds.addRange(fieldNum(HcmPositionWorkerAssignment, ValidFrom)).value(SysQuery::range(DateTimeUtil::minValue(), currentDateTime));
    assignmentQbds.addRange(fieldNum(HcmPositionWorkerAssignment, ValidTo)).value(SysQuery::range(currentDateTime, DateTimeUtil::maxValue()));

    sysTableLookup.addLookupfield(fieldNum(HcmPosition, PositionId), true);
    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}

private boolean isPositionAssigned(HcmPositionRecId _positionRecId)
{
    TransDateTime               currentDateTime = DateTimeUtil::getSystemDateTime();
    HcmPositionWorkerAssignment workerPosition;

    select firstOnly RecId from workerPosition
        where workerPosition.Worker    == workerRecId
           && workerPosition.Position  == _positionRecId
           && workerPosition.ValidFrom <= currentDateTime
           && workerPosition.ValidTo   >= currentDateTime;

    return workerPosition.RecId != 0;
}

private AmountCur findBasicSalary()
{
    TransDate                     currentDate       = systemDateGet();
    TransDateTime                 currentDateTime   = DateTimeUtil::getSystemDateTime();
    DataAreaId                    legalEntity       = curext();
    HcmPosition                   position          = HcmPosition::findByPosition(PositionId.text());
    HcmPositionDetail             positionDetail    = HcmPositionDetail::findByPosition(position.RecId);
    basicSalaryFound = false;
    gradePayroll.clear();

    if (!position)
    {
        return 0;
    }

    if (!positionDetail)
    {
        return 0;
    }

    select firstOnly gradePayroll
        order by gradePayroll.FromDate desc
        where gradePayroll.CompensationLevelId  == positionDetail.NVLegalGrade
           && gradePayroll.LegalEntity          == legalEntity
           && gradePayroll.PayrollEarningCodeId != ''
           && gradePayroll.AdditionalPayrollEarningCodeId != ''
           && gradePayroll.FromDate             <= currentDate
           && gradePayroll.ToDate               >= currentDate;

    if (gradePayroll)
    {
        basicSalaryFound = true;
        return gradePayroll.SalaryAmount;
    }

    return 0;
}

private void calculateSalary()
{
    AmountCur locBsicSalary         = 0;
    AmountCur locAdditionalSalary   = 0;
    AmountCur locTotalSalary        = TotalSalary.realValue();

    if (PositionId.text())
    {
        locBsicSalary      = this.findBasicSalary();
        locAdditionalSalary = locTotalSalary - locBsicSalary;
    }
    else
    {
        basicSalaryFound = false;
    }

    BasicSalary.realValue(locBsicSalary);
    AdditionalSalary.realValue(locAdditionalSalary > 0 ? locAdditionalSalary : 0);
}

private boolean validateInput()
{
    HcmPosition position;

    if (!PositionId.text())
    {
        return checkFailed("Position is required.");
    }

    position = HcmPosition::findByPosition(PositionId.text());

    if (!position || !this.isPositionAssigned(position.RecId))
    {
        return checkFailed("Select a position currently assigned to the worker.");
    }

    if (TotalSalary.realValue() <= 0)
    {
        return checkFailed("Total salary must be greater than zero.");
    }

    this.calculateSalary();

    if (!basicSalaryFound)
    {
        return checkFailed("No active grade-wise payroll setup was found for the selected position.");
    }

    return true;
}

private void updateWorkerPositionEarningCode(PayrollEarningCodeId _earningCodeId, AmountCur _amount)
{
    TransDate                       currentDate = systemDateGet();
    HcmPosition                     position    = HcmPosition::findByPosition(PositionId.text());
    PayrollEarningCode              earningCode = PayrollEarningCode::findByEarningCode(_earningCodeId);
    PayrollWorkerPositionEarningCode workerPositionEarningCode;

    if (!earningCode)
    {
        throw error(strFmt("Payroll earning code '%1' does not exist.", _earningCodeId));
    }

    select firstOnly forUpdate validTimeState(currentDate) workerPositionEarningCode
        where workerPositionEarningCode.Worker      == workerRecId
           && workerPositionEarningCode.Position    == position.RecId
           && workerPositionEarningCode.EarningCode == earningCode.RecId;

    if (workerPositionEarningCode)
    {
        if (workerPositionEarningCode.Formula == _amount)
        {
            return;
        }

        if (workerPositionEarningCode.ValidFrom == currentDate)
        {
            workerPositionEarningCode.validTimeStateUpdateMode(ValidTimeStateUpdate::Correction);
        }
        else
        {
            workerPositionEarningCode.validTimeStateUpdateMode(ValidTimeStateUpdate::CreateNewTimePeriod);
        }

        workerPositionEarningCode.Formula = _amount;
        workerPositionEarningCode.update();
    }
    else
    {
        workerPositionEarningCode.clear();
        workerPositionEarningCode.Worker      = workerRecId;
        workerPositionEarningCode.Position    = position.RecId;
        workerPositionEarningCode.EarningCode = earningCode.RecId;
        workerPositionEarningCode.modifiedField(fieldNum(PayrollWorkerPositionEarningCode, EarningCode));
        workerPositionEarningCode.Formula     = _amount;
        workerPositionEarningCode.ValidFrom   = currentDate;
        workerPositionEarningCode.ValidTo     = gradePayroll.ToDate;
        workerPositionEarningCode.insert();
    }
}

private void saveSalary()
{
    ttsbegin;

    this.updateWorkerPositionEarningCode(
        gradePayroll.PayrollEarningCodeId,
        BasicSalary.realValue());

    this.updateWorkerPositionEarningCode(
        gradePayroll.AdditionalPayrollEarningCodeId,
        AdditionalSalary.realValue());

    ttscommit;
}

public HcmWorkerRecId parmWorkerRecId()
{
    return workerRecId;
}

public HcmPositionRecId parmPositionRecId()
{
    return HcmPosition::findByPosition(PositionId.text()).RecId;
}

public AmountCur parmTotalSalary()
{
    return TotalSalary.realValue();
}

public AmountCur parmBasicSalary()
{
    return BasicSalary.realValue();
}

public AmountCur parmAdditionalSalary()
{
    return AdditionalSalary.realValue();
}

private void refreshCallerForm()
{
    FormRun        callerForm = element.args().caller() as FormRun;
    FormDataSource earningCodeDataSource;

    if (!callerForm)
    {
        return;
    }

    earningCodeDataSource = callerForm.dataSource(formDataSourceStr(HcmWorkerPayroll, WorkerPositionEarningCode));

    if (earningCodeDataSource)
    {
        earningCodeDataSource.research(true);
    }
}

public void lookup()
{
    element.lookupPosition(this);
}

public boolean modified()
{
    boolean ret = super();

    element.calculateSalary();

    return ret;
}

public boolean modified()
{
    boolean ret = super();

    element.calculateSalary();

    return ret;
}

public void clicked()
{
    if (!element.validateInput())
    {
        return;
    }

    element.saveSalary();
    element.refreshCallerForm();

    super();
}
